#!/usr/bin/env bash
# GENERATED by pve/build.sh from pve/install-parts: do not edit, edit the parts and rebuild (ct-install.sh).
# cloud-desktop-host inside a container or VM: idempotent, NON-interactive installer.
#
# This is the in-container half of pve/install.sh (which pushes it into the CT and runs it), but it
# also works on its own in any LXC/Incus/Docker/VM that already has what only a host can give:
# a render node (/dev/dri/renderD*), /dev/uinput, /dev/input/*, /dev/nvidia* and the host's udev
# database at /run/udev (or bind-mounted at /mnt/host-udev). Run as root:
#
#   bash -c "$(curl -fsSL https://raw.githubusercontent.com/chiririll/cloud-desktop-host/v1.2.0/pve/ct-install.sh)" -- --check
#   CT_USER=user INSTALL_STEAM=1 bash -c "$(curl -fsSL …/ct-install.sh)"
#   … -- --update            # bring everything to the latest version (see below)
#
# Prefer a tag in the URL over main. The release bundle it then downloads is verified by SHA256SUMS.
#
# Nothing is asked: a `curl | bash` pipe has no tty. Settings come from the environment:
#   CT_USER=user            session user, created if missing
#   INSTALL_STEAM=1         Steam + Gamescope + MangoHud
#   CDH_INPUT_ISOLATED=0    1: the host gives this CT its own /dev/input (cdh_input_guard), so the shared
#                           udev rule for virtual input is removed; keep: leave that rule alone; 0: install it
#   CDH_GH_REPO=chiririll/cloud-desktop-host   CDH_VERSION=v1.2.0   (empty = latest release)
#   CDH_LOCAL_BUNDLE=<dir>  use <dir>/{cloud-desktop-host,scripts,configs} instead of a download
#   SUNSHINE_PKG=<url|file> Sunshine package (empty = latest release asset for this distro)
#   SUNSHINE_VERSION=<tag>  pin a Sunshine release
#   CLOUD_MOUSE_PKG=<url|file|none>   KCM Cloud Mouse (empty = latest for this distro, skipped if there is none)
#   CSRF_EXTRA=https://gaming.example.org   extra Sunshine web UI origins
#   INSTALL_UPDATE_TIMER=1  weekly systemd timer that runs this script with --update
#   CT_CDH=/opt/cloud-desktop-host   LOG=/var/log/cdh-ct-install.log
#
# Flags: --check (report only), --update, --force-restart (with --update).
#
# Exit codes: 0 done / nothing needed; 10 --check found steps needed (last line: NEEDED=<n>);
#   11 applied, the container must be restarted; 12 applied, the user session was restarted (--update);
#   1 a step failed; 2 usage or unsupported distro.
set -euo pipefail

# ════ install-parts/files/* (inlined by build.sh) ════
get_file() {
  case $1 in
    udev/60-lxc-virtual-input.rules)
      cat <<'CDH_EMBEDDED_EOF'
SUBSYSTEM=="input", KERNEL=="event*", DEVPATH=="/devices/virtual/input/*", OWNER="@HOST_UID@", MODE="0600"
CDH_EMBEDDED_EOF
      ;;
    systemd/cloud-desktop-host.service)
      cat <<'CDH_EMBEDDED_EOF'
[Unit]
Description=cloud-desktop-host session (compositor, KWin, Plasma, Sunshine)

[Service]
Type=simple
# run.sh starts its own D-Bus session (dbus-launch) when this is unset
UnsetEnvironment=DBUS_SESSION_BUS_ADDRESS
ExecStart=@CT_CDH@/scripts/run.sh
# run.sh exits when the compositor dies: bring the whole stack back
Restart=always
RestartSec=5

[Install]
WantedBy=default.target
CDH_EMBEDDED_EOF
      ;;
    systemd/cdh-update.service)
      cat <<'CDH_EMBEDDED_EOF'
[Unit]
Description=cloud-desktop-host update (ct-install.sh --update)
Wants=network-online.target
After=network-online.target

[Service]
Type=oneshot
EnvironmentFile=-/etc/cdh/ct-install.env
# Fetches the installer of the configured release and runs it; a failed download runs nothing.
# 12 = the session was restarted.
ExecStart=/bin/bash -c 's=$$(curl -fsSL @RELEASE_BASE@/ct-install.sh) && exec bash -c "$$s" ct-install --update'
SuccessExitStatus=12
CDH_EMBEDDED_EOF
      ;;
    systemd/cdh-update.timer)
      cat <<'CDH_EMBEDDED_EOF'
[Unit]
Description=Weekly cloud-desktop-host update (skipped while a client is streaming)

[Timer]
OnCalendar=Sun *-*-* 04:00:00
RandomizedDelaySec=1h
Persistent=true

[Install]
WantedBy=timers.target
CDH_EMBEDDED_EOF
      ;;
    *) echo "get_file: no file $1" >&2; return 1 ;;
  esac
}

# ════ install-parts/ct/10-ct-config.sh ════
# ── settings: the environment contract, see the header ─────────
CT_USER=${CT_USER:-user}
INSTALL_STEAM=${INSTALL_STEAM:-1}
CDH_INPUT_ISOLATED=${CDH_INPUT_ISOLATED:-0}
CDH_GH_REPO=${CDH_GH_REPO:-chiririll/cloud-desktop-host}
CDH_VERSION=${CDH_VERSION:-}
CDH_LOCAL_BUNDLE=${CDH_LOCAL_BUNDLE:-}
SUNSHINE_PKG=${SUNSHINE_PKG:-}
SUNSHINE_VERSION=${SUNSHINE_VERSION:-}
CLOUD_MOUSE_PKG=${CLOUD_MOUSE_PKG:-}
CSRF_EXTRA=${CSRF_EXTRA:-}
INSTALL_UPDATE_TIMER=${INSTALL_UPDATE_TIMER:-0}
CT_CDH=${CT_CDH:-/opt/cloud-desktop-host}   # scripts + configs, root-owned, read-only for the user
LOG=${LOG:-/var/log/cdh-ct-install.log}
SUPPORTED_TAGS=(fc43 fc44 fc45 ubuntu2604)   # keep in sync with the matrix in .github/workflows/release.yml

# ── runtime state ──
CHECK_ONLY=0
UPDATE=0
FORCE_RESTART=0
NEEDED=0            # steps still needed (--check)
RESTART_CT=0        # a step needs a container restart (exit 11)
APPLIED=0           # set by step() when it changed something
SESSION_RESTARTED=0
SESSION_APPLIED=0   # the session unit was (re)started by its own step
MANIFEST=''         # "sha256  path" lines of the release bundle, see shared/30-release.sh
BUNDLE_TMP=''       # temp dir of the downloaded bundle, removed on exit
BUNDLE_SKIP=0       # --check without curl: the release can't be looked at
REPO=''             # where scripts/ and configs/ come from (bundle dir)
CDH_BIN=''          # the binary to install
DISTRO='' DISTRO_VERSION='' DISTRO_TAG=''   # set by detect_distro (20-distro.sh)

usage() { echo "usage: ct-install.sh [--check] [--update [--force-restart]]   (settings: see the script header)"; }

parse_args() {
  while (($#)); do
    case "$1" in
      --check|-n) CHECK_ONLY=1 ;;
      --update|-u) UPDATE=1 ;;
      --force-restart) FORCE_RESTART=1 ;;
      -h|--help) usage; exit 0 ;;
      *) echo "unknown option: $1"; usage; exit 2 ;;
    esac
    shift
  done
  if ((FORCE_RESTART && !UPDATE)); then echo "--force-restart only makes sense with --update"; exit 2; fi
}

# ════ install-parts/shared/20-engine.sh ════
# ════════════════════════════════════════════════════════════════
# Shared by install.sh (host) and ct-install.sh (container): output, step engine, embedded files.
#   1. output          msg_*, die, header
#   2. step engine     why, step, require
#   3. embedded files  render_file
# ════════════════════════════════════════════════════════════════

# ── 1. output, community-scripts style ─────────────────────────
if [[ -t 1 || ${CDH_COLOR:-} == 1 ]]; then
  GN=$'\e[32m' YW=$'\e[33m' RD=$'\e[31m' BL=$'\e[36m' DM=$'\e[2m' CL=$'\e[0m'
else
  GN='' YW='' RD='' BL='' DM='' CL=''
fi
msg_info() { printf ' %s…%s %s' "$YW" "$CL" "$1"; }
msg_ok()   { printf '\r\e[K %s✔%s %s%s%s\n' "$GN" "$CL" "$1" "$DM" "${2:+ ($2)}$CL"; }
msg_todo() { printf '\r\e[K %s◦%s %s %s(needed)%s\n' "$BL" "$CL" "$1" "$YW" "$CL"; }
msg_warn() { printf '\r\e[K %s!%s %s\n' "$YW" "$CL" "$1"; }
die()      { printf '\r\e[K %s✘%s %s\n' "$RD" "$CL" "$1"; exit 1; }
header()   { printf '\n%s── %s%s\n' "$BL" "$1" "$CL"; }


APPLIED_ANY=0    # steps applied in this run (update mode: restart the session if > 0)

# ── 2. step engine ─────────────────────────────────────────────
# step "description" check apply
#   check/apply are function names; extra words become arguments
#   ("chk_nocaps sunshine"), so one pair of functions can serve several steps.
#   Checks print WHY they fail (one reason per line, see why()); shown under "needed".
#   Globals: CHECK_ONLY (read), NEEDED (counted in --check), APPLIED (set to 1 if applied).
# require "description" check "hint": a check we can't fix automatically.

# why <reason>: print the reason and fail; the last line of a failing check
why() { echo "$*"; return 1; }

# show_why <check output>: first lines of a check's output, dimmed and indented
show_why() { [[ -n $1 ]] && sed -n '1,8p' <<<"$1" | sed "s/^/     $DM/; s/\$/$CL/"; return 0; }

step() {
  local name=$1 check=$2 apply=$3 rc out
  APPLIED=0

  if out=$($check 2>&1); then msg_ok "$name"; return 0; fi

  if ((CHECK_ONLY)); then
    msg_todo "$name"; show_why "$out"
    NEEDED=$((NEEDED + 1))
    return 0
  fi

  msg_info "$name"
  printf '=== %s %s\n%s\n' "$(date -Is)" "$name" "$out" >>"$LOG"
  set +e; ( set -e; $apply ) >>"$LOG" 2>&1; rc=$?; set -e
  ((rc == 0)) || die "$name: failed (exit $rc), see $LOG"

  if ! out=$($check 2>&1); then
    printf '\r\e[K'; show_why "$out"
    die "$name: still not satisfied after applying, see $LOG"
  fi
  APPLIED=1; APPLIED_ANY=$((APPLIED_ANY + 1))
  msg_ok "$name" "done"
}

require() {
  local name=$1 check=$2 hint=$3 out
  out=$($check 2>&1) && { msg_ok "$name"; return 0; }
  if ((CHECK_ONLY)); then
    msg_todo "$name: $hint"; show_why "$out"
    NEEDED=$((NEEDED + 1))
    return 0
  fi
  show_why "$out"; die "$name: $hint"
}

# call right after a step whose change needs a CT restart
restart_if_applied() { if ((APPLIED)); then RESTART_CT=1; fi; }


# ── 3. embedded files ──────────────────────────────────────────
# install-parts/files/* are inlined by build.sh into get_file() (see build.sh), so the
# installer stays one file. Files may hold @VAR@ placeholders.

# render_file <file> [VAR…]: the file with every @VAR@ replaced by the value of $VAR
render_file() {
  local out v; out=$(get_file "$1"); shift
  for v; do out=${out//@$v@/${!v}}; done
  printf '%s\n' "$out"
}

# ════ install-parts/shared/30-release.sh ════
# ── release bundle: cdh/{cloud-desktop-host,scripts,configs,pve} ──
# Shared: the host script downloads the bundle (which contains ct-install.sh) and pushes it into the CT;
# ct-install.sh downloads it itself when run standalone.
# MANIFEST: "sha256  path" for cloud-desktop-host, scripts/*, configs/*.
# --check only needs this (a few KB), the bundle is downloaded to apply.
release_base() {
  if [[ -z $CDH_VERSION || $CDH_VERSION == latest ]]; then
    echo "https://github.com/$CDH_GH_REPO/releases/latest/download"
  else
    echo "https://github.com/$CDH_GH_REPO/releases/download/$CDH_VERSION"
  fi
}
# The release MANIFEST has one binary line per distro (cloud-desktop-host-<DISTRO_TAG>-x86_64, e.g.
# -fc43- or -ubuntu2604-); keep ours under the plain name used by local_manifest and drop the others.
fetch_manifest() {
  local raw
  raw=$(curl -fsSL "$(release_base)/MANIFEST") || return 1
  MANIFEST=$(sed -n -e "s|  cloud-desktop-host-$DISTRO_TAG-x86_64\$|  cloud-desktop-host|p" \
                    -e '/  cloud-desktop-host-/d;/  \(scripts\|configs\)\//p' <<<"$raw")
  [[ -n $MANIFEST ]]
}
local_manifest() {
  printf '%s  cloud-desktop-host\n' "$(sha256sum <"$CDH_BIN" | cut -d' ' -f1)"
  (cd "$REPO" && find scripts configs -type f | sort | xargs sha256sum)
}
# release lines of MANIFEST that belong inside the CT (scripts/, configs/)
manifest() { grep -E '  (scripts|configs)/' <<<"$MANIFEST"; }

# Downloads + verifies the bundle into BUNDLE_TMP (removed by the EXIT trap in main)
# and points REPO/CDH_BIN at it.
fetch_release() {
  local asset="cdh-$DISTRO_TAG-x86_64.tar.gz" base
  base=$(release_base)
  BUNDLE_TMP=$(mktemp -d /tmp/cdh-release.XXXXXX)
  curl -fsSL -o "$BUNDLE_TMP/$asset" "$base/$asset" || return 1
  curl -fsSL -o "$BUNDLE_TMP/SHA256SUMS" "$base/SHA256SUMS" || return 1
  (cd "$BUNDLE_TMP" && grep " $asset\$" SHA256SUMS | sha256sum -c --quiet -) || return 1
  tar -C "$BUNDLE_TMP" -xzf "$BUNDLE_TMP/$asset"
  REPO=$BUNDLE_TMP/cdh CDH_BIN=$BUNDLE_TMP/cdh/cloud-desktop-host
}

# ════ install-parts/ct/distro/fedora.sh ════
# ── distro backend: Fedora (dnf / rpm) ─────────────────────────
# Implements the interface documented in 20-distro.sh; every function is prefixed fedora_.

fedora_ct_packages() {
  printf '%s\n' dbus-daemon dbus-tools dbus-x11 pipewire wireplumber pipewire-pulseaudio \
    pipewire-utils xorg-x11-server-Xwayland kwin plasma-desktop grim curl libcap xprop \
    xdg-utils kde-cli-tools
}
fedora_steam_packages() { printf '%s\n' steam gamescope mangohud; }   # after RPM Fusion nonfree
fedora_admin_group() { echo wheel; }
fedora_pkg_ext() { echo rpm; }
fedora_sunshine_pattern() { echo "\\.fc$DISTRO_VERSION\\.x86_64\\.rpm"; }
fedora_sunshine_missing_hint() { :; }

# pkg_missing pkg… : prints the missing package names, fails if any
fedora_pkg_missing() {
  local out rc=0 m
  out=$(rpm -q "$@" 2>&1) || rc=$?
  ((rc == 0)) && return 0
  m=$(awk '/is not installed/{print $2}' <<<"$out" | xargs)
  [[ -n $m ]] && { why "missing: $m"; return; }
  why "rpm -q failed: $(head -1 <<<"$out")"
}

# Some %post scripts (udisks2: `udevadm trigger` -> EACCES on /sys/.../uevent in a container) exit non-zero
# although everything is installed. So the exit code is NOT the verdict: callers let step() re-run the check.
fedora_pkg_install() {
  local rc=0
  dnf install -y "$@" || rc=$?
  ((rc == 0)) || echo "package manager exited $rc (usually a container-hostile postinst), verifying afterwards"
  return 0
}

# fedora_pkg_install_file <url|path> [lenient]: dnf takes both
fedora_pkg_install_file() {
  local rc=0
  dnf install -y "$1" || rc=$?
  if ((${2:-0})); then return 0; fi   # e.g. Sunshine's %post fails in a container
  return "$rc"
}

# number of packages with a newer version (0 = up to date)
fedora_pkg_upgrades() {
  local rc=0
  dnf -q check-upgrade >/dev/null 2>&1 || rc=$?
  ((rc == 100)) && echo 1 || echo 0   # dnf does not say how many without parsing; any is enough
}
fedora_pkg_upgrade() {
  local rc=0
  dnf upgrade -y || rc=$?
  ((rc == 0)) || echo "package manager exited $rc, verifying afterwards"
  return 0
}

fedora_pkg_version() { rpm -q --qf '%{VERSION}' "$1"; }

# the installed package called <name> in any case (Sunshine RPM)
fedora_pkg_name_ci() {
  local n
  n=$(rpm -qa --qf '%{NAME}\n' | grep -ix "$1" | head -1)
  [[ -n $n ]] && echo "$n"
}

# ── Steam prerequisites: RPM Fusion nonfree ──
fedora_chk_steamrepos() { pkg_missing rpmfusion-nonfree-release; }
fedora_do_steamrepos()  { dnf install -y "https://mirrors.rpmfusion.org/nonfree/fedora/rpmfusion-nonfree-release-$DISTRO_VERSION.noarch.rpm"; }
fedora_steam_repos_label() { echo "RPM Fusion nonfree"; }
fedora_steam_prepare() { :; }

# ════ install-parts/ct/distro/ubuntu.sh ════
# ── distro backend: Ubuntu (apt / dpkg) ────────────────────────
# Implements the interface documented in 20-distro.sh; every function is prefixed ubuntu_.

# candidate list: verify every name on the 26.04 template
ubuntu_ct_packages() {
  printf '%s\n' dbus dbus-user-session dbus-x11 pipewire wireplumber pipewire-pulse \
    pipewire-audio xwayland kwin-wayland plasma-desktop plasma-workspace polkit-kde-agent-1 \
    grim curl ca-certificates libcap2-bin x11-utils xdg-utils kde-cli-tools
}
ubuntu_steam_packages() { printf '%s\n' steam-installer gamescope mangohud; }   # after i386 + multiverse
ubuntu_admin_group() { echo sudo; }
ubuntu_pkg_ext() { echo deb; }
ubuntu_sunshine_pattern() { echo "ubuntu-${DISTRO_VERSION//./\\.}-amd64\\.deb"; }
ubuntu_sunshine_missing_hint() {
  echo "Build Sunshine from subprojects/sunshine (docs/BUILD.md) and pass it as SUNSHINE_PKG=<file.deb>."
}

APT_ENV=(DEBIAN_FRONTEND=noninteractive NEEDRESTART_MODE=a)

PKG_REFRESHED=0
ubuntu_pkg_refresh() {
  if ((!PKG_REFRESHED)); then apt-get update -q; PKG_REFRESHED=1; fi
  return 0
}

# pkg_missing pkg… : prints the missing package names, fails if any
ubuntu_pkg_missing() {
  local p miss=()
  for p; do
    [[ "$(dpkg-query -W -f='${db:Status-Abbrev}' "$p" 2>/dev/null)" == ii* ]] || miss+=("$p")
  done
  ((${#miss[@]} == 0)) || why "missing: ${miss[*]}"
}

# Some postinst scripts (udisks2: `udevadm trigger` -> EACCES on /sys/.../uevent in a container) exit non-zero
# although everything is installed. So the exit code is NOT the verdict: callers let step() re-run the check.
ubuntu_pkg_install() {
  local rc=0
  ubuntu_pkg_refresh
  env "${APT_ENV[@]}" apt-get install -y "$@" || rc=$?
  ((rc == 0)) || echo "package manager exited $rc (usually a container-hostile postinst), verifying afterwards"
  return 0
}

# ubuntu_pkg_install_file <url|path> [lenient]: apt needs a local .deb (dependencies are resolved)
ubuntu_pkg_install_file() {
  local src=$1 lenient=${2:-0} rc=0 tmp=''
  ubuntu_pkg_refresh
  if [[ $src =~ ^https?:// ]]; then
    tmp=$(mktemp /tmp/cdh-pkg.XXXXXX.deb)
    curl -fsSL -o "$tmp" "$src" || { rm -f "$tmp"; return 1; }
    src=$tmp
  fi
  [[ $src == /* ]] || src=$PWD/$src
  env "${APT_ENV[@]}" apt-get install -y "$src" || rc=$?
  [[ -z $tmp ]] || rm -f "$tmp"
  if ((lenient)); then return 0; fi   # e.g. Sunshine's postinst modprobe/udevadm fail in a container
  return "$rc"
}

# number of packages with a newer version (0 = up to date)
ubuntu_pkg_upgrades() {
  ubuntu_pkg_refresh >&2
  apt-get -s dist-upgrade | grep -c '^Inst ' || true
}
ubuntu_pkg_upgrade() {
  local rc=0
  ubuntu_pkg_refresh
  env "${APT_ENV[@]}" apt-get dist-upgrade -y \
    -o Dpkg::Options::=--force-confold -o Dpkg::Options::=--force-confdef || rc=$?
  ((rc == 0)) || echo "package manager exited $rc, verifying afterwards"
  return 0
}

ubuntu_pkg_version() { dpkg-query -W -f='${Version}' "$1"; }

# the installed package called <name> in any case (sunshine deb)
ubuntu_pkg_name_ci() {
  local n
  n=$(dpkg-query -W -f='${db:Status-Abbrev} ${Package}\n' | awk '$1=="ii"{print $2}' | grep -ix "$1" | head -1)
  [[ -n $n ]] && echo "$n"
}

# ── Steam prerequisites: Steam is 32-bit and lives in multiverse ──
ubuntu_chk_steamrepos() {
  dpkg --print-foreign-architectures | grep -qx i386 || { why "i386 architecture not enabled"; return; }
  grep -qsE '^(Components:|deb ).*[[:space:]]multiverse' /etc/apt/sources.list /etc/apt/sources.list.d/*.sources /etc/apt/sources.list.d/*.list \
    || why "multiverse not enabled in apt sources"
}
ubuntu_do_steamrepos() {
  local f
  dpkg --add-architecture i386
  for f in /etc/apt/sources.list.d/*.sources; do   # deb822
    [[ -f $f ]] && grep -q 'ubuntu\.com' "$f" && sed -i '/^Components:/{/multiverse/!s/$/ multiverse/}' "$f"
  done
  if [[ -f /etc/apt/sources.list ]]; then sed -i '/^deb .*ubuntu\.com/{/multiverse/!s/$/ multiverse/}' /etc/apt/sources.list; fi
  PKG_REFRESHED=0; ubuntu_pkg_refresh
}
ubuntu_steam_repos_label() { echo "i386 + multiverse (Steam)"; }
# the license question would block a non-interactive install
ubuntu_steam_prepare() {
  printf '%s\n' 'steam steam/question select I AGREE' 'steam steam/license note ' | debconf-set-selections
}

# ════ install-parts/ct/20-distro.sh ════
# ── distro detection and dispatch ──────────────────────────────
# detect_distro sets DISTRO (fedora|ubuntu), DISTRO_VERSION (43, 26.04) and DISTRO_TAG (fc43, ubuntu2604),
# the suffix of the release assets.
#
# Everything that differs between distros lives in ct/distro/<distro>.sh, which defines these functions
# prefixed with <distro>_ (fedora_pkg_install, ubuntu_pkg_install, …). The phases never look at $DISTRO:
# they call the generic names below, which forward to the active distro. A new distro = a new
# ct/distro/<id>.sh implementing this interface + a case in detect_distro.
#
#   ct_packages / steam_packages      package names, one per line
#   admin_group                       the group that grants sudo (wheel | sudo)
#   pkg_ext                           rpm | deb
#   pkg_missing pkg…                  why()s and fails if one is not installed
#   pkg_install pkg…                  lenient: the verdict is the re-run check, see step()
#   pkg_install_file src [lenient]    install a url/path
#   pkg_upgrades / pkg_upgrade        count of pending upgrades / do them
#   pkg_version pkg / pkg_name_ci n   installed version / installed name matched case-insensitively
#   sunshine_pattern                  regex of the Sunshine release asset for this distro
#   sunshine_missing_hint             extra advice when there is no such asset
#   steam_repos_label                 title of the step that prepares the repos for Steam
#   chk_steamrepos / do_steamrepos    that step
#   steam_prepare                     runs before the Steam packages are installed

detect_distro() {
  local id ver t ok=0
  [[ -r /etc/os-release ]] || { echo "no /etc/os-release: unsupported system"; exit 2; }
  eval "$(. /etc/os-release; printf 'id=%q ver=%q' "${ID:-}" "${VERSION_ID:-}")"
  case $id in
    fedora) DISTRO=fedora DISTRO_VERSION=$ver DISTRO_TAG=fc$ver ;;
    ubuntu) DISTRO=ubuntu DISTRO_VERSION=$ver DISTRO_TAG=ubuntu${ver//./} ;;
    *) echo "unsupported distro '$id' (supported: ${SUPPORTED_TAGS[*]})"; exit 2 ;;
  esac
  for t in "${SUPPORTED_TAGS[@]}"; do [[ $t == "$DISTRO_TAG" ]] && ok=1; done
  if ((!ok)) && [[ -z $CDH_LOCAL_BUNDLE ]]; then
    echo "$id $ver has no release bundle (supported: ${SUPPORTED_TAGS[*]})"; exit 2
  fi
  return 0
}

ct_packages()             { "${DISTRO}_ct_packages"; }
steam_packages()          { "${DISTRO}_steam_packages"; }
admin_group()             { "${DISTRO}_admin_group"; }
pkg_ext()                 { "${DISTRO}_pkg_ext"; }
pkg_missing()             { "${DISTRO}_pkg_missing" "$@"; }
pkg_install()             { "${DISTRO}_pkg_install" "$@"; }
pkg_install_file()        { "${DISTRO}_pkg_install_file" "$1" "${2:-0}"; }
pkg_upgrades()            { "${DISTRO}_pkg_upgrades"; }
pkg_upgrade()             { "${DISTRO}_pkg_upgrade"; }
pkg_version()             { "${DISTRO}_pkg_version" "$1"; }
pkg_name_ci()             { "${DISTRO}_pkg_name_ci" "$1"; }
sunshine_pattern()        { "${DISTRO}_sunshine_pattern"; }
sunshine_missing_hint()   { "${DISTRO}_sunshine_missing_hint"; }
steam_repos_label()       { "${DISTRO}_steam_repos_label"; }
chk_steamrepos()          { "${DISTRO}_chk_steamrepos"; }
do_steamrepos()           { "${DISTRO}_do_steamrepos"; }
steam_prepare()           { "${DISTRO}_steam_prepare"; }

# ════ install-parts/ct/25-ct-helpers.sh ════
# ── helpers that read facts from inside the container ──────────
as_user()        { runuser -l "$CT_USER" -c "$1"; }
# the CT user's systemd --user instance: user_systemctl enable --now foo.service
user_systemctl() { as_user "XDG_RUNTIME_DIR=/run/user/\$(id -u) systemctl --user $*"; }

# NVIDIA driver version of the HOST: the module's sysfs file is visible in an LXC; /proc/driver/nvidia
# needs the /dev/nvidia* nodes the host mapped in
host_driver() {
  local v; v=$(cat /sys/module/nvidia/version 2>/dev/null) || v=''
  [[ -n $v ]] || v=$(sed -n 's/.*Kernel Module  *\([0-9][0-9.]*\).*/\1/p' /proc/driver/nvidia/version 2>/dev/null | head -1)
  [[ -n $v ]] && echo "$v"
}

# uid of the CT user as the HOST sees it: shifted by the idmap of an unprivileged CT, plain in a VM or privileged CT
host_uid() {
  local u; u=$(id -u "$CT_USER" 2>/dev/null) || u=1000
  awk -v u="$u" '$1 <= u && u < $1 + $3 {print $2 + u - $1; f = 1; exit} END {if (!f) print u}' /proc/self/uid_map
}

ct_ip() {
  local ip
  ip=$(ip -4 -o addr show scope global 2>/dev/null | awk '{sub(/\/.*/, "", $4); print $4; exit}') || ip=''
  [[ -n $ip ]] || ip=$(hostname -I 2>/dev/null | awk '{print $1}')
  echo "${ip:-<container ip>}"
}

# step "… has no file caps" "chk_nocaps <binary>" "do_nocaps <binary>"
chk_nocaps() { bash -c 'f=$(readlink -f "$(command -v "$1")") && [ -z "$(getcap "$f")" ]' _ "$1"; }
do_nocaps()  { bash -c 'setcap -r "$(readlink -f "$(command -v "$1")")"' _ "$1"; }

# ════ install-parts/ct/30-phase-system.sh ════
# ── phase: system (udev db, packages, user, NVIDIA userspace) ──
chk_curl() { pkg_missing curl ca-certificates; }
do_curl()  { pkg_install curl ca-certificates; }

# The host's udev database: the container has no udev of its own, libinput/KWin need the host's.
# In an LXC it is bind-mounted at /mnt/host-udev (lxc.mount.entry, see 52-phase-container.sh) and re-mounted
# on /run/udev through fstab; on a VM /run/udev is populated by its own udev and nothing is needed.
UDEV_FSTAB_LINE='/mnt/host-udev  /run/udev  none  bind  0 0'   # no ro: the source is already ro (lxc.mount.entry) and a ro remount is EPERM in an unprivileged CT
UDEV_FSTAB_OLD='/mnt/host-udev  /run/udev  none  bind,ro  0 0'
chk_udevdb() {
  ls /run/udev/data 2>/dev/null | grep -q . || { why "/run/udev/data is empty: the host's udev database is not mounted"; return; }
  if [[ -d /mnt/host-udev ]]; then grep -qxF "$UDEV_FSTAB_LINE" /etc/fstab || why "/etc/fstab has no bind mount of /mnt/host-udev"; fi
}
do_udevdb() {
  if [[ ! -d /mnt/host-udev ]]; then
    echo "no /mnt/host-udev: bind-mount the host's /run/udev (read-only) there, or at /run/udev"
    return 1
  fi
  sed -i "\|^$UDEV_FSTAB_OLD\$|d" /etc/fstab   # older versions wrote bind,ro
  grep -qxF "$UDEV_FSTAB_LINE" /etc/fstab || echo "$UDEV_FSTAB_LINE" >>/etc/fstab
  if mountpoint -q /run/udev && ls /run/udev/data >/dev/null 2>&1; then return 0; fi
  mkdir -p /run/udev   # absent when no udev runs in the CT (Ubuntu); /run is tmpfs
  mount /run/udev
}

# Sunshine's virtual input devices must be owned by the CT user's uid as seen from the host.
# With the input guard the CT has its own /dev/input and cdh-input-node sets the owner (host side); this rule
# is only for containers on the host's shared /dev/input (CDH_INPUT_ISOLATED=0). "keep" leaves it alone.
INPUT_RULE=/etc/udev/rules.d/60-lxc-virtual-input.rules
input_rule_txt() { local HOST_UID; HOST_UID=$(host_uid); render_file udev/60-lxc-virtual-input.rules HOST_UID; }
chk_inrule() { [[ "$(cat $INPUT_RULE 2>/dev/null)" == "$(input_rule_txt)" ]] || why "$INPUT_RULE missing or outdated"; }
do_inrule()  { input_rule_txt >$INPUT_RULE; udevadm control --reload; }
chk_no_inrule() { [[ ! -e $INPUT_RULE ]] || why "$INPUT_RULE still gives every virtual input device to one uid"; }
do_no_inrule()  { rm -f "$INPUT_RULE"; udevadm control --reload; }
phase_input_rule() {
  case $CDH_INPUT_ISOLATED in
    1) step "shared udev rule ${INPUT_RULE##*/} removed" chk_no_inrule do_no_inrule ;;
    keep) msg_warn "other containers still share /dev/input: ${INPUT_RULE##*/} left as it is" ;;
    *) step "host udev rule: Sunshine virtual input → host uid $(host_uid)" chk_inrule do_inrule ;;
  esac
}

chk_pkgs() { local p; mapfile -t p < <(ct_packages); pkg_missing "${p[@]}"; }
do_pkgs()  { local p; mapfile -t p < <(ct_packages); pkg_install "${p[@]}"; }

chk_user() {
  id "$CT_USER" >/dev/null 2>&1 || { why "user '$CT_USER' does not exist"; return; }
  local g groups; groups=$(id -nG "$CT_USER")
  for g in video render input; do
    getent group "$g" >/dev/null || continue
    grep -qw "$g" <<<"$groups" || { why "'$CT_USER' is not in group $g"; return; }
  done
}
do_user() {
  id "$CT_USER" >/dev/null 2>&1 || useradd -m -s /bin/bash "$CT_USER"
  local g
  for g in video render input "$(admin_group)"; do
    if getent group "$g" >/dev/null; then usermod -aG "$g" "$CT_USER"; fi
  done
}

# the .run installer puts the libraries in /usr/lib64 (Fedora) or /usr/lib/x86_64-linux-gnu (Debian)
nv_libs_present() { ls /usr/lib64/libnvidia-glcore.so."$1" /usr/lib/x86_64-linux-gnu/libnvidia-glcore.so."$1" >/dev/null 2>&1; }
chk_nvuser() {
  local drv; drv=$(host_driver) || { why "cannot read the host's NVIDIA driver version (/sys/module/nvidia, /proc/driver/nvidia)"; return; }
  nv_libs_present "$drv" || why "NVIDIA userspace $drv not installed"
}
do_nvuser() {
  local drv; drv=$(host_driver)
  curl -fsSLo /tmp/nvidia.run "https://download.nvidia.com/XFree86/Linux-x86_64/$drv/NVIDIA-Linux-x86_64-$drv.run"
  sh /tmp/nvidia.run --no-kernel-module --install-compat32-libs -s
  rm -f /tmp/nvidia.run
}

chk_smi() { nvidia-smi -L; }

chk_linger() { [[ -e "/var/lib/systemd/linger/$CT_USER" ]]; }
do_linger()  { loginctl enable-linger "$CT_USER"; }

phase_system() {
  header "System"
  step "host udev db at /run/udev" chk_udevdb do_udevdb
  phase_input_rule
  step "packages (KWin, Plasma, PipeWire, Xwayland…)" chk_pkgs do_pkgs
  step "user '$CT_USER' (video,render,input)" chk_user do_user
  step "NVIDIA userspace $(host_driver || echo '?') (matches host)" chk_nvuser do_nvuser
  require "nvidia-smi works in the container" chk_smi "check the /dev/nvidia* nodes and the driver version, see $LOG"
  step "linger for '$CT_USER'" chk_linger do_linger
}

# ════ install-parts/ct/40-phase-cdh.sh ════
# ── phase: release bundle, CDH, Sunshine, Cloud Mouse, Steam ───
# Decides where scripts/configs/binary come from: CDH_LOCAL_BUNDLE or the release. Sets MANIFEST.
phase_bundle() {
  header "Release"
  if [[ -n $CDH_LOCAL_BUNDLE ]]; then
    REPO=$CDH_LOCAL_BUNDLE CDH_BIN=$CDH_LOCAL_BUNDLE/cloud-desktop-host
    [[ -x $CDH_BIN && -d $REPO/scripts ]] || die "CDH_LOCAL_BUNDLE=$CDH_LOCAL_BUNDLE has no cloud-desktop-host + scripts/"
    MANIFEST=$(local_manifest)
    msg_ok "Using local bundle" "$CDH_LOCAL_BUNDLE"
  elif ! command -v curl >/dev/null; then
    BUNDLE_SKIP=1   # only reachable with --check: do_curl installs it otherwise
    msg_warn "no curl yet: the release can't be compared (run without --check once)"
  elif ((CHECK_ONLY)) && fetch_manifest; then
    msg_ok "Release ${CDH_VERSION:-latest} manifest" "bundle not downloaded in check mode"
  else
    ((CHECK_ONLY)) && die "could not read the MANIFEST of release ${CDH_VERSION:-latest} from $CDH_GH_REPO (no $DISTRO_TAG build?)"
    msg_info "Downloading release ${CDH_VERSION:-latest} from $CDH_GH_REPO"
    fetch_release || die "could not download/verify cdh-$DISTRO_TAG-x86_64.tar.gz from $CDH_GH_REPO (${CDH_VERSION:-latest})"
    MANIFEST=$(local_manifest)
    msg_ok "Release ${CDH_VERSION:-latest} downloaded" "sha256 ok"
  fi
}

CDH_INSTALLED=/usr/local/bin/cloud-desktop-host
chk_cdh() {
  [[ -x $CDH_INSTALLED ]] || { why "$CDH_INSTALLED not installed"; return; }
  [[ "$(awk '$2=="cloud-desktop-host"{print $1}' <<<"$MANIFEST")" == "$(sha256sum <"$CDH_INSTALLED" | cut -d' ' -f1)" ]] \
    || why "$CDH_INSTALLED differs from the release/local build"
}
do_cdh() {
  # the previous binary stays as .prev for a one-line rollback; mv instead of cp: the old one may be running
  if [[ -x $CDH_INSTALLED ]]; then cp -p "$CDH_INSTALLED" "$CDH_INSTALLED.prev"; fi
  install -m 0755 "$CDH_BIN" "$CDH_INSTALLED.new"
  mv -f "$CDH_INSTALLED.new" "$CDH_INSTALLED"
}

chk_scripts() {
  [[ -d $CT_CDH ]] || { why "$CT_CDH missing"; return; }
  local out rc=0
  out=$(cd "$CT_CDH" && manifest | sha256sum -c --quiet - 2>/dev/null) || rc=$?
  sed -n 's/: FAILED.*/ differs or is missing/p' <<<"$out"
  return "$rc"
}
do_scripts() {
  mkdir -p "$CT_CDH"
  tar -C "$REPO" -c scripts configs | tar -C "$CT_CDH" --no-same-owner --no-same-permissions -x
  chown -R root:root "$CT_CDH"
  chmod -R u=rwX,go=rX "$CT_CDH"
  chmod 0755 "$CT_CDH"/scripts/*.sh
}

# ── Sunshine ──
# The package is called "Sunshine" (RPM) or "sunshine" (deb): matched case-insensitively.
# SUNSHINE_JSON: the GitHub release (SUNSHINE_VERSION, else latest), loaded once.
sunshine_load() {
  [[ -n ${SUNSHINE_JSON:-} ]] && return 0
  local ep=latest; [[ -z $SUNSHINE_VERSION ]] || ep=tags/$SUNSHINE_VERSION
  SUNSHINE_JSON=$(curl -fsSL "https://api.github.com/repos/LizardByte/Sunshine/releases/$ep") && [[ -n $SUNSHINE_JSON ]]
}
sunshine_tag() { sunshine_load && grep -o '"tag_name": *"[^"]*"' <<<"$SUNSHINE_JSON" | head -1 | sed 's/.*"\([^"]*\)"$/\1/'; }
sunshine_asset() {
  local pat; pat=$(sunshine_pattern)
  sunshine_load && grep -oi '"browser_download_url": *"[^"]*'"$pat"'"' <<<"$SUNSHINE_JSON" | head -1 | sed 's/.*"\(https:[^"]*\)"/\1/'
}
chk_sunshine() {
  local name want have
  name=$(pkg_name_ci sunshine) || { why "Sunshine package not installed"; return; }
  # update mode: the latest (or pinned) release must be installed, unless a package was given explicitly
  ((UPDATE)) && [[ -z $SUNSHINE_PKG ]] || return 0
  want=$(sunshine_tag) || want=''
  if [[ -z $want ]]; then echo "Sunshine: could not look up the latest release, version not compared" >&2; return 0; fi
  have=$(pkg_version "$name")
  [[ $have == "${want#v}"* ]] || why "Sunshine $have installed, $want available"
}
do_sunshine() {
  local src=$SUNSHINE_PKG
  if [[ -z $src ]]; then
    src=$(sunshine_asset) || src=''
    if [[ -z $src ]]; then
      echo "no $DISTRO_TAG asset in the Sunshine release ${SUNSHINE_VERSION:-latest}."
      sunshine_missing_hint
      return 1
    fi
    echo "Sunshine: $src"
  fi
  pkg_install_file "$src" 1   # postinst modprobe/udevadm fail in a container
}

chk_ssconf() { as_user 'test -s ~/.config/sunshine/sunshine.conf && test -s ~/.config/sunshine/apps.json'; }
do_ssconf() {
  local ip origins apps=apps-desktop.json
  ip=$(ct_ip)
  origins="https://$ip:47990${CSRF_EXTRA:+,$CSRF_EXTRA}"
  as_user "mkdir -p ~/.config/sunshine
    test -s ~/.config/sunshine/sunshine.conf || printf '%s\n' \
      'capture = wlr' 'encoder = nvenc' 'gamepad = xone' 'system_tray = disabled' \
      'csrf_allowed_origins = $origins' > ~/.config/sunshine/sunshine.conf"
  if as_user 'test -s ~/.config/sunshine/apps.json'; then return 0; fi
  if ((INSTALL_STEAM)); then apps=apps.json; fi   # no Steam: only the Desktop app
  as_user "cp $CT_CDH/configs/sunshine/$apps ~/.config/sunshine/apps.json"
}

# ── KCM Cloud Mouse ──
# Default: the release asset of this distro. Not built for every release: skip with a warning instead of failing.
CLOUD_MOUSE_REPO=chiririll/kcm-cloud-mouse
cloudmouse_src() {
  echo "${CLOUD_MOUSE_PKG:-https://github.com/$CLOUD_MOUSE_REPO/releases/latest/download/kcm-cloud-mouse-$DISTRO_TAG-x86_64.$(pkg_ext)}"
}
chk_cloudmouse() {
  local want have
  pkg_missing kcm-cloud-mouse || return 1
  ((UPDATE)) && [[ -z $CLOUD_MOUSE_PKG ]] || return 0
  want=$(curl -fsSL "https://api.github.com/repos/$CLOUD_MOUSE_REPO/releases/latest" 2>/dev/null \
    | grep -o '"tag_name": *"[^"]*"' | head -1 | sed 's/.*"\([^"]*\)"$/\1/') || want=''
  want=${want#v}; have=$(pkg_version kcm-cloud-mouse)
  # only compare plain numeric versions: an odd tag scheme must not make every update reinstall
  [[ $want =~ ^[0-9]+(\.[0-9]+)*$ ]] || return 0
  [[ $have == "$want"* ]] || why "Cloud Mouse $have installed, $want available"
}
do_cloudmouse() { pkg_install_file "$(cloudmouse_src)"; }
phase_cloudmouse() {
  [[ $CLOUD_MOUSE_PKG != none ]] || return 0
  if [[ -z $CLOUD_MOUSE_PKG ]] && command -v curl >/dev/null && ! curl -fsIL -o /dev/null "$(cloudmouse_src)"; then
    msg_warn "KCM Cloud Mouse: no $DISTRO_TAG build in kcm-cloud-mouse releases, skipped (set CLOUD_MOUSE_PKG=<file> to install your own)"
    return 0
  fi
  step "KCM Cloud Mouse (System Settings → Input Devices)" chk_cloudmouse do_cloudmouse
}

# ── Steam ── (the repo prerequisites differ per distro: chk_/do_steamrepos, see 20-distro.sh)
chk_steam() { local p; mapfile -t p < <(steam_packages); pkg_missing "${p[@]}"; }
do_steam() {
  local p; mapfile -t p < <(steam_packages)
  steam_prepare
  pkg_install "${p[@]}"
}
phase_steam() {
  if ((INSTALL_STEAM)); then
    step "$(steam_repos_label)" chk_steamrepos do_steamrepos
    step "Steam + Gamescope + MangoHud" chk_steam do_steam
    step "Gamescope has no file caps" "chk_nocaps gamescope" "do_nocaps gamescope"
  fi
}

phase_cdh() {
  header "cloud-desktop-host, Sunshine, Steam"
  if ((BUNDLE_SKIP)); then
    msg_warn "CDH binary and scripts: not compared (no release information)"
  else
    step "cloud-desktop-host binary" chk_cdh do_cdh
    step "CDH scripts + configs in $CT_CDH" chk_scripts do_scripts
  fi
  step "Sunshine" chk_sunshine do_sunshine
  step "Sunshine has no file caps (AT_SECURE breaks ENet)" "chk_nocaps sunshine" "do_nocaps sunshine"
  step "Sunshine config (kept if it already exists)" chk_ssconf do_ssconf
  phase_cloudmouse
  phase_steam
}

# ════ install-parts/ct/50-phase-services.sh ════
# ── phase: user service ────────────────────────────────────────
# The whole stack (compositor, KWin, Plasma, Sunshine) as a user service,
# started at boot thanks to linger. Last, so it starts with everything installed.
SESSION_UNIT=cloud-desktop-host.service
SESSION_UNIT_FILE=/etc/systemd/user/$SESSION_UNIT
session_unit_txt() { render_file systemd/cloud-desktop-host.service CT_CDH; }
chk_session() {
  [[ "$(cat "$SESSION_UNIT_FILE" 2>/dev/null)" == "$(session_unit_txt)" ]] \
    || { why "$SESSION_UNIT_FILE missing or outdated"; return; }
  user_systemctl is-enabled -q "$SESSION_UNIT" || why "$SESSION_UNIT not enabled for '$CT_USER'"
}
do_session() {
  mkdir -p "${SESSION_UNIT_FILE%/*}"
  session_unit_txt >"$SESSION_UNIT_FILE"
  rm -f /etc/systemd/user/cdh-sunshine.service   # earlier Sunshine-only unit
  user_systemctl daemon-reload
  user_systemctl enable --now "$SESSION_UNIT"
}

phase_services() {
  header "Session"
  step "user service $SESSION_UNIT (starts at boot)" chk_session do_session
  SESSION_APPLIED=$APPLIED
}

# ════ install-parts/ct/60-phase-update.sh ════
# ── update mode (--update) ─────────────────────────────────────
# Not a separate script: the step engine already means "make the system match the target". Update mode moves
# the target to "latest" (version checks in chk_sunshine / chk_cloudmouse, the release bundle, which is
# `latest` unless CDH_VERSION is pinned) and adds the package upgrade and the session restart below.

chk_upgrades() {
  local n; n=$(pkg_upgrades)
  ((n == 0)) || why "$n package(s) can be upgraded"
}
do_upgrades() { pkg_upgrade; }

# Runs before the Sunshine/Gamescope no-caps steps: a Sunshine package upgrade restores its file
# capability and ENet then breaks silently (AT_SECURE).
phase_update_pkgs() {
  ((UPDATE)) || return 0
  step "distro packages up to date" chk_upgrades do_upgrades
}

# Weekly update from inside the container. The settings are kept in /etc/cdh/ct-install.env.
UPDATE_ENV=/etc/cdh/ct-install.env
update_env_txt() {
  printf '%s=%s\n' CT_USER "$CT_USER" INSTALL_STEAM "$INSTALL_STEAM" CDH_INPUT_ISOLATED "$CDH_INPUT_ISOLATED" \
    CDH_GH_REPO "$CDH_GH_REPO" CDH_VERSION "$CDH_VERSION" SUNSHINE_VERSION "$SUNSHINE_VERSION" \
    CSRF_EXTRA "$CSRF_EXTRA" CT_CDH "$CT_CDH"
}
update_unit_txt() { local RELEASE_BASE; RELEASE_BASE=$(release_base); render_file "systemd/$1" RELEASE_BASE; }
chk_updtimer() {
  [[ "$(cat $UPDATE_ENV 2>/dev/null)" == "$(update_env_txt)" ]] || { why "$UPDATE_ENV missing or outdated"; return; }
  local u
  for u in cdh-update.service cdh-update.timer; do
    [[ "$(cat "/etc/systemd/system/$u" 2>/dev/null)" == "$(update_unit_txt "$u")" ]] || { why "$u missing or outdated"; return; }
  done
  systemctl is-enabled -q cdh-update.timer || why "cdh-update.timer not enabled"
}
do_updtimer() {
  local u
  mkdir -p "${UPDATE_ENV%/*}"
  update_env_txt >"$UPDATE_ENV"
  for u in cdh-update.service cdh-update.timer; do update_unit_txt "$u" >"/etc/systemd/system/$u"; done
  systemctl daemon-reload
  systemctl enable --now cdh-update.timer
}
phase_update_timer() {
  [[ $INSTALL_UPDATE_TIMER == 1 ]] || return 0
  step "weekly update timer (cdh-update.timer)" chk_updtimer do_updtimer
}

# A Moonlight client is streaming: the prep scripts create the marker, the undo scripts remove it.
client_connected() { [[ -e "/run/user/$(id -u "$CT_USER")/cdh/stream-active" ]]; }

# After any change: restart the session so it runs the new versions, unless somebody is playing.
phase_update_finish() {
  local changed=$((APPLIED_ANY - SESSION_APPLIED))   # the session step starts the unit itself
  ((UPDATE && !CHECK_ONLY)) || return 0
  if ((changed <= 0)); then msg_ok "Session unchanged" "nothing was updated"; return 0; fi
  header "Restarting the session"
  if client_connected && ((!FORCE_RESTART)); then
    msg_warn "$changed step(s) updated, but a client is streaming: session not restarted. Restart when done: systemctl --user restart $SESSION_UNIT (as $CT_USER), or re-run with --force-restart"
    return 0
  fi
  user_systemctl restart "$SESSION_UNIT" || die "could not restart $SESSION_UNIT"
  SESSION_RESTARTED=1
  msg_ok "Session restarted" "$changed step(s) updated"
}

# ════ install-parts/ct/90-ct-main.sh ════
# ── main: the order of things lives here ───────────────────────
# To add a step: write chk_*/do_* in the matching phase part and call `step` from its phase_* function.
preflight() {
  local c missing=()
  [[ $EUID -eq 0 ]] || die "run as root"
  for c in awk sed tar sha256sum getent runuser useradd; do
    command -v "$c" >/dev/null || missing+=("$c")
  done
  if ((${#missing[@]})); then die "missing: ${missing[*]}"; fi
  [[ $CT_USER =~ ^[a-z_][a-z0-9_-]{0,31}$ ]] || die "CT_USER '$CT_USER' is not a valid user name"
  [[ $INSTALL_STEAM =~ ^[01]$ ]] || die "INSTALL_STEAM must be 1 or 0, got '$INSTALL_STEAM'"
  [[ $INSTALL_UPDATE_TIMER =~ ^[01]$ ]] || die "INSTALL_UPDATE_TIMER must be 1 or 0, got '$INSTALL_UPDATE_TIMER'"
  [[ $CDH_INPUT_ISOLATED =~ ^(0|1|keep)$ ]] || die "CDH_INPUT_ISOLATED must be 0, 1 or keep, got '$CDH_INPUT_ISOLATED'"
  if ((!CHECK_ONLY)); then mkdir -p "${LOG%/*}" && : >>"$LOG"; fi
}

cleanup() { if [[ -n $BUNDLE_TMP ]]; then rm -rf -- "$BUNDLE_TMP"; fi; }

main() {
  parse_args "$@"
  trap cleanup EXIT
  detect_distro
  preflight
  if ((CHECK_ONLY)); then echo "${YW}check mode: nothing will be changed${CL}"; fi
  echo "${DM}$DISTRO $DISTRO_VERSION ($DISTRO_TAG)$( ((UPDATE)) && echo ', update mode')${CL}"

  header "Bootstrap"
  step "curl + CA certificates (to download releases)" chk_curl do_curl
  phase_bundle
  phase_system
  phase_update_pkgs
  phase_cdh
  phase_services
  phase_update_timer
  phase_update_finish

  echo
  if ((CHECK_ONLY)); then
    if ((NEEDED)); then echo "${YW}$NEEDED step(s) needed.${CL} Run without --check to apply."
    else echo "${GN}Everything is in place.${CL}"; fi
    echo "NEEDED=$NEEDED"
    if ((NEEDED)); then exit 10; fi
    exit 0
  fi
  echo "${GN}Done.${CL} Log: $LOG"
  if ((RESTART_CT)); then exit 11; fi
  if ((SESSION_RESTARTED)); then exit 12; fi
  exit 0
}

main "$@"
